// FactOperations — generated by src/powerbi/build_assets.py from FactOperations.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "FactOperations.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"operation_id", type text},
        {"department_id", type text},
        {"operation_date", type date},
        {"operation_type", type text},
        {"process_name", type text},
        {"total_transactions", Int64.Type},
        {"successful_transactions", Int64.Type},
        {"failed_transactions", Int64.Type},
        {"processing_time_minutes", type number},
        {"operational_cost", type number},
        {"operational_status", type text},
        {"cost_sign_corrected", type logical},
        {"cost_outlier", type logical},
        {"operational_cost_original", type number},
        {"processing_time_imputed", type logical},
        {"success_rate", type number},
        {"failure_rate", type number},
        {"cost_per_transaction", type number},
        {"total_processing_hours", type number},
        {"operation_month", type text},
        {"process_key", Int64.Type}
    }, "en-US")
in
    Typed
